        vector<long long> last(n + 1, 0);
        for (int i = 1; i <= n; i++) {
            int bl = 0; long long bg = -1;
            for (int j = 0; j < i; j++) {
                long long s = pre[i] - pre[j];
                if (s >= last[j] && (ln[j] + 1 > bl || (ln[j] + 1 == bl && (bg == -1 || s < bg)))) {
                    bl = ln[j] + 1; bg = s;
                }
            }
            if (bl == 0) { ln[i] = 1; last[i] = pre[i]; }
            else { ln[i] = bl; last[i] = bg; }
        }
        return ln[n];
    }
};

