        n = len(nums)
        pre = [0] * (n + 1)
        for i, x in enumerate(nums):
            pre[i + 1] = pre[i] + x
        st = []  # entries: [key, length, index]
        for i in range(1, n + 1):
            lo, hi, pos = 0, len(st) - 1, -1
            while lo <= hi:
                m = (lo + hi) // 2
                if st[m][0] <= pre[i]:
                    pos = m
                    lo = m + 1
                else:
                    hi = m - 1
            if pos >= 0:
                ln = st[pos][1] + 1
                last = pre[i] - pre[st[pos][2]]
            else:
                ln, last = 1, pre[i]
            key = pre[i] + last
            while st and st[-1][1] <= ln and st[-1][0] >= key:
                st.pop()
            st.append([key, ln, i])
        return st[-1][1]

