                if (st[m][0] <= pre[i]) { pos = m; lo = m + 1; }
                else hi = m - 1;
            }
            long long ln, last;
            if (pos >= 0) {
                ln = st[pos][1] + 1;
                last = pre[i] - pre[(int)st[pos][2]];
            } else { ln = 1; last = pre[i]; }
            long long key = pre[i] + last;
            while (!st.empty() && st.back()[1] <= ln && st.back()[0] >= key)
