class Solution {
    public int findMaximumLength(int[] nums) {
        int n = nums.length;
        long[] pre = new long[n + 1];
        for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + nums[i];
        ArrayDeque<long[]> st = new ArrayDeque<>(); // {key, len, index}
        for (int i = 1; i <= n; i++) {
            Object[] arr = st.toArray();
            int lo = 0, hi = arr.length - 1, pos = -1;
            while (lo <= hi) {
                int m = (lo + hi) >>> 1;
                if (((long[]) arr[m])[0] <= pre[i]) { pos = m; lo = m + 1; }
                else hi = m - 1;
            }
            long ln, last;
            if (pos >= 0) {
                long[] e = (long[]) arr[pos];
                ln = e[1] + 1;
                last = pre[i] - pre[(int) e[2]];
            } else { ln = 1; last = pre[i]; }
            long key = pre[i] + last;
            while (!st.isEmpty()) {
                long[] t = st.peekLast();
                if (t[1] <= ln && t[0] >= key) st.pollLast(); else break;
            }
            st.addLast(new long[]{key, ln, i});
        }
        return (int) st.peekLast()[1];
    }
}

